import React, { useState, useEffect } from 'react';
import { getPendingPayments, confirmPayment, getOrderById } from '../services/api';
import OrderVerificationModal from './OrderVerificationModal';
import { useTheme } from '../context/ThemeContext';
import axios from 'axios';

const API_URL = process.env.REACT_APP_API_URL || 'http://localhost:5000/api';

// Create admin API instance for payment verification
const adminApi = axios.create({
  baseURL: API_URL,
  headers: {
    'Content-Type': 'application/json'
  }
});

// Add admin token to headers
adminApi.interceptors.request.use((config) => {
  const adminToken = localStorage.getItem('adminToken');
  if (adminToken) {
    config.headers.Authorization = `Bearer ${adminToken}`;
  }
  return config;
});

const PaymentConfirmation = () => {
  const { isDarkMode } = useTheme();
  const [pendingPayments, setPendingPayments] = useState([]);
  const [loading, setLoading] = useState(true);
  const [confirming, setConfirming] = useState({});
  const [formData, setFormData] = useState({});
  const [verificationModal, setVerificationModal] = useState({
    isOpen: false,
    orderId: null,
    paymentMethod: null,
    amount: null
  });

  useEffect(() => {
    fetchPendingPayments();
    const interval = setInterval(fetchPendingPayments, 30000); // Refresh every 30 seconds
    return () => clearInterval(interval);
  }, []);

  const fetchPendingPayments = async () => {
    try {
      setLoading(true);
      const res = await getPendingPayments();
      console.log('🔍 Pending payments response:', res.data);
      setPendingPayments(res.data.pendingPayments || []);
    } catch (error) {
      console.error('Error fetching pending payments:', error);
      // Try debug endpoint
      try {
        const debugRes = await fetch('/api/payment/debug');
        const debugData = await debugRes.json();
        console.log('🐛 Debug info:', debugData);
      } catch (debugError) {
        console.error('Debug endpoint failed:', debugError);
      }
    } finally {
      setLoading(false);
    }
  };

  const handleQuickVerify = async (orderId, amount, paymentMethod) => {
    // Open verification modal instead of direct action
    setVerificationModal({
      isOpen: true,
      orderId,
      paymentMethod,
      amount
    });
  };

  const handleVerificationConfirm = async (orderId, paymentMethod) => {
    try {
      setConfirming(prev => ({ ...prev, [orderId]: true }));

      let endpoint, action;
      if (paymentMethod === 'cod') {
        // For COD orders - confirm order
        endpoint = `/api/payment/confirm-order/${orderId}`;
        action = 'confirm';
      } else {
        // For online payments - verify payment
        endpoint = `/api/payment/quick-verify/${orderId}`;
        action = 'verify';
      }

      const token = localStorage.getItem('token');
      const response = await fetch(endpoint, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify({
          verifiedBy: 'admin'
        })
      });

      if (!response.ok) {
        console.error('🔍 API Response Error:', response.status, response.statusText);
        const errorData = await response.json().catch(() => ({}));
        console.error('🔍 Error Data:', errorData);
        throw new Error(`API Error: ${response.status}`);
      }

      const result = await response.json();
      console.log(`🚀 Quick ${action} completed:`, result);

      // Remove from pending list
      setPendingPayments(prev => prev.filter(p => p.orderId !== orderId));

      const message = paymentMethod === 'cod' 
        ? `✅ Order confirmed and placed automatically for ${orderId}!\nAmount: ₹${verificationModal.amount}\nUser will receive order confirmation.`
        : `✅ Payment verified and Order placed automatically for ${orderId}!\nAmount: ₹${verificationModal.amount}\nUser will receive success notification.`;

      alert(message);
    } catch (error) {
      console.error(`Error in quick ${paymentMethod === 'cod' ? 'confirmation' : 'verification'}:`, error);
      alert(`Failed to ${paymentMethod === 'cod' ? 'confirm order' : 'verify payment'}`);
    } finally {
      setConfirming(prev => ({ ...prev, [orderId]: false }));
    }
  };

  const closeVerificationModal = () => {
    setVerificationModal({
      isOpen: false,
      orderId: null,
      paymentMethod: null,
      amount: null
    });
  };

  const handleConfirmPayment = async (orderId, amount) => {
    try {
      setConfirming(prev => ({ ...prev, [orderId]: true }));

      const data = formData[orderId] || {};
      await confirmPayment(orderId, amount, data.transactionId, data.notes);

      // Remove from pending list
      setPendingPayments(prev => prev.filter(p => p.orderId !== orderId));

      alert(`Payment confirmed for order ${orderId}`);
    } catch (error) {
      console.error('Error confirming payment:', error);
      alert('Failed to confirm payment');
    } finally {
      setConfirming(prev => ({ ...prev, [orderId]: false }));
    }
  };

  const handleSimulatePayment = async (orderId, amount) => {
    try {
      setConfirming(prev => ({ ...prev, [orderId]: true }));

      const token = localStorage.getItem('token');
      const response = await fetch(`/api/payment/simulate-payment/${orderId}`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify({
          amount: amount,
          transactionId: 'UPI_SIM_' + Date.now()
        })
      });

      const result = await response.json();
      console.log('💰 Payment simulated:', result);

      // Remove from pending list
      setPendingPayments(prev => prev.filter(p => p.orderId !== orderId));

      alert(`✅ Payment simulated for order ${orderId} - User will see success notification!`);
    } catch (error) {
      console.error('Error simulating payment:', error);
      alert('Failed to simulate payment');
    } finally {
      setConfirming(prev => ({ ...prev, [orderId]: false }));
    }
  };

  const handleInputChange = (orderId, field, value) => {
    setFormData(prev => ({
      ...prev,
      [orderId]: {
        ...prev[orderId],
        [field]: value
      }
    }));
  };

  const formatTime = (timestamp) => {
    return new Date(timestamp).toLocaleString();
  };

  const createTestPayment = async () => {
    try {
      const testOrderId = 'test_' + Date.now();
      const testAmount = 299;
      const endpoint = '/api/payment/test';
      const token = localStorage.getItem('token');
      const response = await fetch(endpoint, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify({
          orderId: testOrderId,
          amount: testAmount,
          transactionId: formData[testOrderId]?.transactionId,
          notes: formData[testOrderId]?.notes
        })
      });

      const result = await response.json();
      console.log('🧪 Test payment created:', result);

      // Refresh the list
      fetchPendingPayments();
    } catch (error) {
      console.error('Error creating test payment:', error);
    }
  };

  if (loading) {
    return (
      <div className="flex justify-center py-8">
        <div className="relative">
          <div className="w-16 h-16 border-4 border-red-200 border-t-red-600 rounded-full animate-spin"></div>
          <div className="absolute inset-0 flex items-center justify-center">
            <div className="w-8 h-8 bg-gradient-to-br from-red-500 to-orange-500 rounded-full animate-pulse"></div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className={`rounded-3xl border-2 ${isDarkMode ? 'border-white/10 bg-gray-800/50' : 'border-gray-200 bg-white/70'} backdrop-blur-xl shadow-xl p-8`}>
      <div className="flex items-center justify-between mb-8">
        <h2 className={`text-2xl font-bold ${isDarkMode ? 'text-white' : 'text-gray-800'}`}>
          Pending Orders & Payments Confirmation
        </h2>
        <div className="flex items-center gap-2">
          <div className={`w-3 h-3 rounded-full ${pendingPayments.length > 0 ? 'bg-orange-500 animate-pulse' : 'bg-green-500'}`}></div>
          <span className={`text-sm font-medium ${isDarkMode ? 'text-gray-300' : 'text-gray-600'}`}>
            {pendingPayments.length} pending
          </span>
        </div>
      </div>

      {pendingPayments.length === 0 ? (
        <div className={`text-center py-16 rounded-2xl ${isDarkMode ? 'bg-gray-900/50 border border-white/10' : 'bg-gray-50/80 border border-gray-200'}`}>
          <div className="w-20 h-20 mx-auto mb-6 rounded-3xl bg-gradient-to-br from-orange-100 to-orange-200 dark:from-orange-900/50 dark:to-orange-800/50 flex items-center justify-center">
            <svg className="w-10 h-10 text-orange-600 dark:text-orange-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
            </svg>
          </div>
          <h3 className={`text-xl font-semibold mb-3 ${isDarkMode ? 'text-white' : 'text-gray-800'}`}>
            No pending payments
          </h3>
          <p className={`mb-6 ${isDarkMode ? 'text-gray-400' : 'text-gray-600'}`}>
            All payments have been verified and processed
          </p>
          <button
            onClick={createTestPayment}
            className="px-6 py-3 bg-gradient-to-r from-orange-500 to-red-500 text-white rounded-xl font-medium hover:from-orange-600 hover:to-red-600 transform transition-all duration-200 hover:scale-[1.02] shadow-lg hover:shadow-xl"
          >
            🧪 Create Test Payment
          </button>
        </div>
      ) : (
        <div className="space-y-4">
          {pendingPayments.map((payment) => (
            <div key={payment.orderId} id={`payment-${payment.orderId}`} className={`group rounded-2xl border-2 ${isDarkMode ? 'border-white/10 bg-gray-900/50' : 'border-gray-200 bg-white/50'} backdrop-blur-sm p-6 transition-all duration-300 hover:shadow-lg hover:scale-[1.01]`}>
              <div className="flex justify-between items-start mb-4">
                <div className="flex-1">
                  <div className="flex items-center gap-3 mb-3">
                    <div className={`w-12 h-12 rounded-xl ${payment.paymentMethod === 'cod' ? 'bg-blue-500/20' : 'bg-purple-500/20'} flex items-center justify-center`}>
                      <span className="text-2xl">{payment.paymentMethod === 'cod' ? '💵' : '💳'}</span>
                    </div>
                    <div>
                      <h3 className={`font-bold text-lg ${isDarkMode ? 'text-white' : 'text-gray-800'}`}>
                        Order: {payment.orderId}
                      </h3>
                      <span className={`inline-flex items-center px-3 py-1 rounded-full text-xs font-medium ${
                        payment.paymentMethod === 'cod' 
                          ? 'bg-blue-100 text-blue-800 dark:bg-blue-900/30 dark:text-blue-300' 
                          : 'bg-purple-100 text-purple-800 dark:bg-purple-900/30 dark:text-purple-300'
                      }`}>
                        {payment.paymentMethod === 'cod' ? 'Cash on Delivery' : 'Online Payment'}
                      </span>
                    </div>
                  </div>
                  <div className="space-y-2">
                    <div className="flex items-center gap-2">
                      <svg className={`w-4 h-4 ${isDarkMode ? 'text-gray-400' : 'text-gray-500'}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2m0-8c1.11 0 2.08.402 2.599 1M12 8V7m0 1v8m0 0v1m0-1c-1.11 0-2.08-.402-2.599-1M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
                      </svg>
                      <span className={`font-semibold text-lg ${isDarkMode ? 'text-green-400' : 'text-green-600'}`}>₹{payment.amount}</span>
                    </div>
                    <div className="flex items-center gap-2">
                      <svg className={`w-4 h-4 ${isDarkMode ? 'text-gray-400' : 'text-gray-500'}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" />
                      </svg>
                      <span className={`text-sm ${isDarkMode ? 'text-gray-300' : 'text-gray-600'}`}>{formatTime(payment.timestamp)}</span>
                    </div>
                    {payment.paymentMethod === 'online' && (
                      <div className="flex items-center gap-2">
                        <svg className={`w-4 h-4 ${isDarkMode ? 'text-gray-400' : 'text-gray-500'}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
                          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15" />
                        </svg>
                        <span className={`text-sm ${isDarkMode ? 'text-gray-300' : 'text-gray-600'}`}>Attempts: {payment.attempts}</span>
                      </div>
                    )}
                  </div>
                </div>
                <div className="text-right">
                  <span className={`inline-flex items-center px-3 py-1.5 rounded-full text-xs font-medium ${
                    payment.status === 'pending_confirmation' 
                      ? 'bg-orange-100 text-orange-800 dark:bg-orange-900/30 dark:text-orange-300' 
                      : 'bg-yellow-100 text-yellow-800 dark:bg-yellow-900/30 dark:text-yellow-300'
                  }`}>
                    <div className="w-1.5 h-1.5 rounded-full mr-1.5 bg-orange-500 animate-pulse"></div>
                    {payment.status === 'pending_confirmation' ? 'Confirmation Pending' : 'Payment Pending'}
                  </span>
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-4">
                <div>
                  <label className={`block text-sm font-medium mb-2 ${isDarkMode ? 'text-gray-200' : 'text-gray-700'}`}>
                    Transaction ID (optional)
                  </label>
                  <input
                    type="text"
                    value={formData[payment.orderId]?.transactionId || ''}
                    onChange={(e) => handleInputChange(payment.orderId, 'transactionId', e.target.value)}
                    className={`w-full px-4 py-2 rounded-xl border-2 transition-all duration-200 focus:ring-2 focus:ring-orange-500 focus:border-transparent ${
                      isDarkMode 
                        ? 'bg-gray-800/50 border-gray-600 text-white placeholder-gray-400' 
                        : 'bg-white/50 border-gray-300 text-gray-900 placeholder-gray-500'
                    }`}
                    placeholder="Enter transaction ID"
                  />
                </div>
                <div>
                  <label className={`block text-sm font-medium mb-2 ${isDarkMode ? 'text-gray-200' : 'text-gray-700'}`}>
                    Notes (optional)
                  </label>
                  <input
                    type="text"
                    value={formData[payment.orderId]?.notes || ''}
                    onChange={(e) => handleInputChange(payment.orderId, 'notes', e.target.value)}
                    className={`w-full px-4 py-2 rounded-xl border-2 transition-all duration-200 focus:ring-2 focus:ring-orange-500 focus:border-transparent ${
                      isDarkMode 
                        ? 'bg-gray-800/50 border-gray-600 text-white placeholder-gray-400' 
                        : 'bg-white/50 border-gray-300 text-gray-900 placeholder-gray-500'
                    }`}
                    placeholder="Add notes"
                  />
                </div>
              </div>

              <div className="flex flex-wrap gap-3 mb-4">
                <button
                  onClick={() => handleQuickVerify(payment.orderId, payment.amount, payment.paymentMethod)}
                  disabled={confirming[payment.orderId]}
                  className="px-4 py-2 bg-gradient-to-r from-green-500 to-emerald-500 text-white rounded-xl font-semibold hover:from-green-600 hover:to-emerald-600 transform transition-all duration-200 hover:scale-[1.02] disabled:opacity-50 disabled:cursor-not-allowed disabled:transform-none shadow-lg hover:shadow-xl"
                >
                  {confirming[payment.orderId] 
                    ? (payment.paymentMethod === 'cod' ? 'Confirming...' : 'Verifying...') 
                    : (payment.paymentMethod === 'cod' ? '🚀 Quick Confirm & Place Order' : '🚀 Quick Verify & Place Order')
                  }
                </button>
                {payment.paymentMethod === 'online' && (
                  <button
                    onClick={() => handleConfirmPayment(payment.orderId, payment.amount)}
                    disabled={confirming[payment.orderId]}
                    className="px-4 py-2 bg-gradient-to-r from-blue-500 to-indigo-500 text-white rounded-xl font-semibold hover:from-blue-600 hover:to-indigo-600 transform transition-all duration-200 hover:scale-[1.02] disabled:opacity-50 disabled:cursor-not-allowed disabled:transform-none shadow-lg hover:shadow-xl"
                  >
                    {confirming[payment.orderId] ? 'Confirming...' : '📋 Detailed Verify'}
                  </button>
                )}
                {payment.paymentMethod === 'online' && (
                  <button
                    onClick={() => handleSimulatePayment(payment.orderId, payment.amount)}
                    disabled={confirming[payment.orderId]}
                    className="px-4 py-2 bg-gradient-to-r from-purple-500 to-pink-500 text-white rounded-xl font-semibold hover:from-purple-600 hover:to-pink-600 transform transition-all duration-200 hover:scale-[1.02] disabled:opacity-50 disabled:cursor-not-allowed disabled:transform-none shadow-lg hover:shadow-xl"
                  >
                    {confirming[payment.orderId] ? 'Simulating...' : '🎯 Test Payment'}
                  </button>
                )}
                {payment.paymentMethod === 'online' && (
                  <button
                    onClick={() => window.open(`tel:*99#`, '_blank')}
                    className="px-4 py-2 border-2 border-gray-300 text-gray-700 rounded-xl font-semibold hover:bg-gray-50 transform transition-all duration-200 hover:scale-[1.02] dark:border-gray-600 dark:text-gray-300 dark:hover:bg-gray-800"
                  >
                    📱 Check UPI
                  </button>
                )}
              </div>

              <div className={`p-3 rounded-xl text-sm ${
                payment.paymentMethod === 'cod' 
                  ? 'bg-blue-50 text-blue-700 dark:bg-blue-900/30 dark:text-blue-300' 
                  : 'bg-green-50 text-green-700 dark:bg-green-900/30 dark:text-green-300'
              }`}>
                <strong>🚀 Quick Workflow:</strong> 
                {payment.paymentMethod === 'cod' 
                  ? ' Click "Quick Confirm & Place Order" → Order automatically placed! User gets order confirmation.'
                  : ' Check UPI app → Click "Quick Verify & Place Order" → Order automatically placed! User gets payment notification.'
                }
              </div>
            </div>
          ))}
        </div>
      )}

      <div className={`mt-8 flex justify-between items-center p-4 rounded-xl ${isDarkMode ? 'bg-gray-900/50 border border-white/10' : 'bg-gray-50/80 border border-gray-200'}`}>
        <button
          onClick={fetchPendingPayments}
          className="px-6 py-3 bg-gradient-to-r from-orange-500 to-red-500 text-white rounded-xl font-medium hover:from-orange-600 hover:to-red-600 transform transition-all duration-200 hover:scale-[1.02] shadow-lg hover:shadow-xl"
        >
          🔄 Refresh
        </button>
        <div className={`text-sm ${isDarkMode ? 'text-gray-400' : 'text-gray-600'}`}>
          Auto-refresh every 30 seconds
        </div>
      </div>

      {/* Order Verification Modal */}
      <OrderVerificationModal
        isOpen={verificationModal.isOpen}
        onClose={closeVerificationModal}
        orderId={verificationModal.orderId}
        paymentMethod={verificationModal.paymentMethod}
        amount={verificationModal.amount}
        onConfirm={handleVerificationConfirm}
      />
    </div>
  );
};

export default PaymentConfirmation;
